UPLOAD_TOOL_TO_STEP_TYPE = {
    "avrdude": "UPLOAD_FIRMWARE_AVRDUDE",
    "esptool.py": "UPLOAD_FIRMWARE_ESPTOOL",
    "openocd": "UPLOAD_FIRMWARE_OPENOCD",
    "stm32cubeprogrammer": "UPLOAD_FIRMWARE_STM32CUBEPROGRAMMER",
}
STEP_TYPE_TO_UPLOAD_TOOL = {v: k for k, v in UPLOAD_TOOL_TO_STEP_TYPE.items()}


def split_upload_firmware_forwards(apps, schema_editor):
    TestStep = apps.get_model("testing", "TestStep")
    for step in TestStep.objects.filter(step_type="UPLOAD_FIRMWARE"):
        config = dict(step.config or {})
        new_type = UPLOAD_TOOL_TO_STEP_TYPE.get(config.pop("upload_tool", None), "UPLOAD_FIRMWARE_AVRDUDE")
        step.step_type = new_type
        step.config = config
        step.save(update_fields=["step_type", "config"])


