    # no old field to map them back to.
    TestStep = apps.get_model("testing", "TestStep")
    for step in TestStep.objects.filter(step_type__in=STEP_TYPE_TO_UPLOAD_TOOL):
        config = dict(step.config or {})
        config["upload_tool"] = STEP_TYPE_TO_UPLOAD_TOOL[step.step_type]
        step.step_type = "UPLOAD_FIRMWARE"
        step.config = config
        step.save(update_fields=["step_type", "config"])


